const fs=require('fs'),cp=require('child_process'),crypto=require('crypto');
const TARGET=process.env.TARGET_FILE,TARGET_SHA=process.env.TARGET_SHA,PARENT_SHA=process.env.PARENT_SHA,PARENT_BLOB=process.env.PARENT_BLOB,TARGET_BLOB=process.env.TARGET_BLOB,HASH=process.env.TARGET_HASH,BYTES=Number(process.env.TARGET_BYTES);
const sh=c=>cp.execSync(c,{encoding:'utf8'}).trim();const assert=(x,m)=>{if(!x)throw new Error(m)};
function parse(src){const lines=src.split(/\r?\n/);let depth=0,sp=[],ap=[],sel=null;const ds=[],stack=[],re=/^\s*([\w-]+)\s*:\s*(.*?)\s*;\s*$/,norm=p=>p.join(' ').replace(/\{\s*$/,'').replace(/\s+/g,' ').trim();for(let i=0;i<lines.length;i++){const line=lines[i],t=line.trim(),o=(line.match(/\{/g)||[]).length,c=(line.match(/\}/g)||[]).length;if(!sel){if(ap.length){if(t)ap.push(t);if(line.includes('{')){stack.push({type:'at',header:norm(ap),depthBefore:depth});ap=[];}}else if(t.startsWith('@')&&!t.includes(';')){if(line.includes('{'))stack.push({type:'at',header:norm([t]),depthBefore:depth});else ap=[t];}else if(sp.length){if(t)sp.push(t);if(line.includes('{')){sel=norm(sp);sp=[];stack.push({type:'rule',selector:sel,depthBefore:depth});}}else if(t&&!t.startsWith('/*')&&!t.startsWith('*')&&t!=='*/'&&t!=='}'&&!t.startsWith('@')&&!line.includes(';')){sp=[t];if(line.includes('{')){sel=norm(sp);sp=[];stack.push({type:'rule',selector:sel,depthBefore:depth});}}}if(sel){const m=line.match(re);if(m){const raw=m[2].trim(),important=/\s*!important\s*$/i.test(raw),context=stack.filter(x=>x.type==='at').map(x=>x.header).join(' || ');ds.push({line:i+1,selector:sel,property:m[1].toLowerCase(),value:raw,important,context});}}depth+=o-c;while(stack.length&&depth<=stack[stack.length-1].depthBefore){const p=stack.pop();if(p.type==='rule')sel=null;}}const last=new Map(),dead=[];for(let i=ds.length-1;i>=0;i--){const d=ds[i],k=`${d.context} >>> ${d.selector} >>> ${d.property}`,l=last.get(k);if(l&&(!d.important||l.important))dead.push({...d,winnerLine:l.line,winnerValue:l.value,winnerImportant:l.important});if(!l||d.important||!l.important)last.set(k,d);}return{declarations:ds,dead:dead.sort((a,b)=>a.line-b.line)};}
assert(sh('git rev-parse HEAD')===TARGET_SHA,'wrong permanent SHA');assert(sh(`git hash-object ${TARGET}`)===TARGET_BLOB,'permanent blob drift');
const permanent=fs.readFileSync(TARGET);assert(permanent.length===BYTES,`permanent bytes ${permanent.length}`);const permanentHash=crypto.createHash('sha256').update(permanent).digest('hex');assert(permanentHash===HASH,`permanent hash ${permanentHash}`);const current=parse(permanent.toString('utf8'));assert(current.declarations.length===720&&current.dead.length===0,`permanent parse ${current.declarations.length}/${current.dead.length}`);
const parent=cp.execFileSync('git',['show',`${PARENT_SHA}:${TARGET}`]);const parentBlob=sh(`git rev-parse ${PARENT_SHA}:${TARGET}`);assert(parentBlob===PARENT_BLOB,`parent blob ${parentBlob}`);const p=parse(parent.toString('utf8'));assert(p.declarations.length===912&&p.dead.length===192,'parent parse drift');assert(new Set(p.dead.map(d=>d.selector)).size===46,'parent selector drift');const identical=p.dead.filter(d=>d.value===d.winnerValue&&d.important===d.winnerImportant).length;assert(identical===48&&p.dead.length-identical===144,'parent identity drift');assert(p.dead.every(d=>!d.important&&!d.winnerImportant&&d.winnerLine>d.line),'parent cascade drift');const ctx=new Map();for(const d of p.dead){const k=d.context||'<global>';ctx.set(k,(ctx.get(k)||0)+1);}assert(ctx.size===3&&ctx.get('<global>')===166&&ctx.get('@media (max-width: 640px)')===14&&ctx.get('@media (max-width: 720px)')===12,'parent context drift');
const src=parent.toString('utf8'),fin=/\r?\n$/.test(src),lines=src.split(/\r?\n/);if(fin&&lines.at(-1)==='')lines.pop();for(const d of [...p.dead].sort((a,b)=>b.line-a.line)){assert(lines[d.line-1]?.trim().startsWith(d.property+':'),'parent line mismatch '+d.line);lines.splice(d.line-1,1);}const rebuilt=Buffer.from(lines.join('\n')+(fin?'\n':''));const rebuiltHash=crypto.createHash('sha256').update(rebuilt).digest('hex');assert(rebuiltHash===HASH,`rebuilt hash ${rebuiltHash}`);assert(rebuilt.length===BYTES,`rebuilt bytes ${rebuilt.length}`);assert(Buffer.compare(rebuilt,permanent)===0,'permanent bytes differ from independent reconstruction');console.log(`EXACT BYTE IDENTITY PASS|sha=${TARGET_SHA}|parent=${PARENT_SHA}|parentBlob=${PARENT_BLOB}|targetBlob=${TARGET_BLOB}|hash=${HASH}|bytes=${BYTES}|decl=912->720|dead=192->0|selectors=46|identical=48|changed=144|contexts=166/14/12`);
